(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
Sensor1_Fault := FALSE;
Sensor2_Fault := FALSE;
Sensor3_Fault := FALSE;
Alarm_Voting_Error := FALSE;
Healthy_Sensors_Count := 3;

LT_101(
    PV_High := 380.0,
    PV_Low := 20.0,
    Scaling_Slope := 25.0,
    Scaling_Offset := -100.0,
    Alarm_Enable := TRUE);
XV_105(
    Timeout := T#5s);
M102_XV105NotClosed_NOT := NOT XV_105.FB_Closed;
M102_Inhibit_OR := M102_XV105NotClosed_NOT OR LT_101.General_Fault;
LV_103(
    Open_Limit := 100.0,
    Close_Limit := 0.0);
HopperLevelAbove20_GT := (LV_103.Feedback_Pos > 20.0);
M102_InhibitNot_NOT := NOT M102_Inhibit_OR;
M102_RestartDelay_TON(
    IN := M102_InhibitNot_NOT,
    PT := T#60s);
M102_StartPermissive_AND := HopperLevelAbove20_GT AND XV_105.FB_Closed AND M102_RestartDelay_TON.Q AND M_102_Start_Request;
M102_StopCmd_OR := M_102_Stop_Request OR M102_Inhibit_OR;
M_102(
    Start_Cmd := M102_StartPermissive_AND,
    Stop_Cmd := M102_StopCmd_OR,
    Accel_Ramp := T#2s,
    Decel_Ramp := T#2s,
    Inhibit := M102_Inhibit_OR);
XV_102(
    Timeout := T#5s,
    Inhibit := M_102.FB_Fault);
XV_104(
    Timeout := T#5s,
    Inhibit := M_102.FB_Fault);
FC101_ValvesOpen_AND := XV_102.FB_Opened AND XV_104.FB_Opened;
FC101_ValvesNotOpen_NOT := NOT FC101_ValvesOpen_AND;
FC101_Inhibit_OR := FC101_ValvesNotOpen_NOT OR LT_101.General_Fault OR M_102.FB_Fault;
FC_101(
    AUTO := TRUE,
    PV := LT_101.PV,
    SP := 250.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    KP := 3.0,
    TR := 1.2,
    TD := 0.3,
    Deviation_Limit := 5.0,
    Inhibit := FC101_Inhibit_OR);
FV_106(
    Control_Signal := FC_101.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Timeout := T#5s,
    Inhibit := LT_101.General_Fault);
FlowDeviationAlarm_TON(
    IN := FC_101.Deviation_Alarm,
    PT := T#30s);

(* Outputs published to other sections / HMI. *)
FC_101_MV_to_FV106 := FC_101.XOUT;
LT_101_Flow_PV := LT_101.PV;
Flow_High_Alarm := LT_101.High_Alarm;
Flow_Low_Alarm := LT_101.Low_Alarm;
Flow_Deviation_Alarm_30s := FlowDeviationAlarm_TON.Q;
M_102_VSD_Speed_Out := M_102.Speed_Out;

DT_301();
PIT_103(
    Scaling_Slope := 31.25,
    Scaling_Offset := -125.0);
PT_101();
PIC104Inhibit_OR := PT_101.Low_Alarm OR PT_101.High_Alarm OR DT_301.High_Alarm OR PIT_103.General_Fault;
PIC104Auto_NOT := NOT PIC104Inhibit_OR;
PIC_104(
    AUTO := PIC104Auto_NOT,
    PV := PIT_103.PV,
    SP := 250.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := -3.0,
    TR := 1.2,
    TD := 0.1,
    PV_High := 275.0,
    PV_Low := 200.0,
    Deviation_Limit := 12.5,
    Inhibit := PIC104Inhibit_OR);
XV_102_OPEN_FB();
PERM_XV102_OPEN(
    Bool_In := XV_102_OPEN_FB.DI_Out);
XV102NotOpen_NOT := NOT PERM_XV102_OPEN.Bool_Out;
XV_107_OPEN_FB();
PERM_XV107_OPEN(
    Bool_In := XV_107_OPEN_FB.DI_Out);
XV107NotOpen_NOT := NOT PERM_XV107_OPEN.Bool_Out;
FV106Inhibit_OR := XV102NotOpen_NOT OR XV107NotOpen_NOT OR PT_101.High_Alarm OR PIT_103.General_Fault;
FV_106(
    Control_Signal := PIC_104.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Timeout := T#2S,
    Inhibit := FV106Inhibit_OR);
SystemFault_OR := PT_101.General_Fault OR DT_301.General_Fault;
SystemEnable_NOT := NOT SystemFault_OR;
XV_102(
    Open_Cmd := SystemEnable_NOT,
    Close_Cmd := SystemFault_OR,
    Inhibit := SystemFault_OR);
XV_107(
    Open_Cmd := SystemEnable_NOT,
    Close_Cmd := SystemFault_OR,
    Inhibit := SystemFault_OR);

(* Outputs published to other sections / HMI. *)
PIT103_Pressure_kPa := PIT_103.PV;
PT101_UpstreamPressure_kPa := PT_101.PV;
DT301_PulpDensity_Pct := DT_301.PV;
PIC104_ControlOutput_to_FV106_Pct := PIC_104.XOUT;
FV106_ValvePositionFeedback_Pct := FV_106.Feedback_Pos;

CT_501(
    Scaling_Slope := 0.1875,
    Scaling_Offset := 1.25,
    Alarm_Enable := TRUE);
LT_501(
    Alarm_Enable := TRUE);
LT501_LevelNotOK_OR := LT_501.Low_Alarm OR LT_501.General_Fault;
PT_502(
    Alarm_Enable := TRUE);
PT502_NotInRange_OR := PT_502.High_Alarm OR PT_502.Low_Alarm OR PT_502.General_Fault;
FC502_Inhibit_OR := LT501_LevelNotOK_OR OR PT502_NotInRange_OR OR CT_501.General_Fault;
FC_502(
    AUTO := TRUE,
    PV := CT_501.PV,
    SP := 3.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 2.2,
    TR := 0.7,
    TD := 0.0,
    PV_High := 4.0,
    PV_Low := 2.0,
    Inhibit := FC502_Inhibit_OR);
FV_502(
    Control_Signal := FC_502.XOUT,
    Manual_Mode := FALSE,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FC502_Inhibit_OR);
PGT_501(
    Alarm_Enable := TRUE);
PGT501_OutOfRange_OR := PGT_501.High_Alarm OR PGT_501.Low_Alarm OR PGT_501.General_Fault;
M_501(
    Inhibit := PGT501_OutOfRange_OR);
SELT_501(
    Scaling_Slope := 0.0625,
    Scaling_Offset := -0.05,
    Alarm_Enable := TRUE);
INTLK_M501_RUNNING(
    Bool_In := M_501.FB_Running);
PlateGapInRange_NOT := NOT PGT501_OutOfRange_OR;
INTLK_PLATE_GAP_IN_RANGE(
    Bool_In := PlateGapInRange_NOT);
SEL_Enable_AND := INTLK_M501_RUNNING.Bool_Out AND INTLK_PLATE_GAP_IN_RANGE.Bool_Out;
SEL_Inhibit_NOT := NOT SEL_Enable_AND;
SELC_501(
    AUTO := TRUE,
    PV := SELT_501.PV,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 1.8,
    TR := 0.5,
    TD := 0.1,
    PV_High := 1.1,
    PV_Low := 0.3,
    Inhibit := SEL_Inhibit_NOT);
PGA_501(
    Control_Signal := SELC_501.XOUT,
    Manual_Mode := FALSE,
    Open_Limit := 100.0,
    Close_Limit := 0.0);
LevelAbove20_NOT := NOT LT501_LevelNotOK_OR;
INTLK_LEVEL_ABOVE_20(
    Bool_In := LevelAbove20_NOT);
PT502_InRange_NOT := NOT PT502_NotInRange_OR;
PERM_PT502_IN_RANGE(
    Bool_In := PT502_InRange_NOT);

(* Outputs published to other sections / HMI. *)
CT501_Consistency_PV_Pct := CT_501.PV;
FC502_MV_to_FV502_Pct := FC_502.XOUT;
SELT501_SEL_PV_WsPerMm2 := SELT_501.PV;
SELC501_MV_to_PGA501_Pct := SELC_501.XOUT;
LT501_Level_PV_Pct := LT_501.PV;
PT502_Pressure_PV_kPa := PT_502.PV;
PGT501_PlateGap_PV_mm := PGT_501.PV;

CT_601(
    Alarm_Enable := TRUE);
FT_601(
    PV_High := 500.0,
    PV_Low := 10.0,
    Alarm_Enable := TRUE);
PIT_601(
    PV_Low := 300.0,
    Alarm_Enable := TRUE);
VT_601(
    Alarm_Enable := TRUE);
FS_601(
    Alarm_OnFalse := TRUE);
P_601_RUN(
    Alarm_OnFalse := TRUE);
CT_Failure := CT_601.High_Alarm OR CT_601.Low_Alarm OR CT_601.General_Fault;
FT_Failure := FT_601.High_Alarm OR FT_601.Low_Alarm OR FT_601.General_Fault;
MinFlow_Fault := NOT FS_601.Bool_Out;
PumpRun_Fault := NOT P_601_RUN.Bool_Out;
Inhibit_Any := PumpRun_Fault OR MinFlow_Fault OR PIT_601.Low_Alarm OR VT_601.Low_Alarm OR CT_Failure OR FT_Failure;
Auto_Enable := NOT Inhibit_Any;
FFIC_601(
    Auto := Auto_Enable,
    PrimaryPV := CT_601.PV,
    SecondaryPV := FT_601.PV,
    RatioSP := 2.5,
    Bias := FFIC601_Bias,
    TrimKp := 0.1,
    TrimTi := T#2s,
    MV_MIN := 10.0,
    MV_MAX := 500.0,
    Inhibit := Inhibit_Any);
FIC_601(
    AUTO := Auto_Enable,
    PV := FT_601.PV,
    SP := FFIC_601.SlaveSP,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 20.0,
    Inhibit := Inhibit_Any);
FV_601(
    Control_Signal := FIC_601.XOUT,
    Manual_Mode := Inhibit_Any,
    Manual_Position := 20.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := Inhibit_Any);
ProcessUpset_Timer(
    IN := CT601_RateHigh,
    PT := T#10s);
SlaveSP_TooHigh := (FFIC_601.SlaveSP > 500.0);
SlaveSP_TooLow := (FFIC_601.SlaveSP < 10.0);
SlaveSP_LimitAlarm := SlaveSP_TooHigh OR SlaveSP_TooLow;

(* Outputs published to other sections / HMI. *)
ALM_601 := SlaveSP_LimitAlarm;
ALM_602 := CT_Failure;
ALM_603 := FT_Failure;
ALM_604 := ProcessUpset_Timer.Q;
CT_601_PV := CT_601.PV;
FT_601_PV := FT_601.PV;
FT_601_SP := FFIC_601.SlaveSP;
PIT_601_PV := PIT_601.PV;
VT_601_PV := VT_601.PV;
FS_601_MinFlow_OK := FS_601.Bool_Out;
P_601_Run_OK := P_601_RUN.Bool_Out;
MasterInhibit := Inhibit_Any;
Process_Permissives_OK := Auto_Enable;

MM_701(
    Raw_Signal := MM701_Raw_mA,
    PV_High := 58.0,
    PV_Low := 46.0,
    Scaling_Slope := 1.25,
    Scaling_Offset := 35.0,
    Alarm_Enable := TRUE);
PT_701(
    Raw_Signal := PT701_Raw,
    Scaling_Slope := 1.0,
    Scaling_Offset := 0.0,
    Alarm_Enable := TRUE);
TT_102(
    Raw_Signal := TT102_Raw,
    Scaling_Slope := 1.0,
    Scaling_Offset := 0.0,
    Alarm_Enable := TRUE);
MoistureTrip_GT := (MM_701.PV > 65.0);
PV_101(
    Control_Signal := LIC_701.XOUT,
    Manual_Mode := FailCloseTrip_OR,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0);
FailCloseTrip_OR := TT_102.High_Alarm OR MoistureTrip_GT OR PT_701.High_Alarm OR PV_101.Position_Error;
LoopInhibit_OR := MM_701.General_Fault OR FailCloseTrip_OR;
CS_701(
    Bool_In := CS701_ON);
HS_701(
    Bool_In := HS701_ON);
SB_701(
    Bool_In := SB701_SheetBreak);
SheetPresent_NOT := NOT SB_701.Bool_Out;
PressLoopPermissive_AND := HS_701.Bool_Out AND CS_701.Bool_Out AND SheetPresent_NOT;
LIC_701(
    AUTO := PressLoopPermissive_AND,
    PV := MM_701.PV,
    SP := 52.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := PV_101.Feedback_Pos,
    KP := 3.0,
    TR := 1.2,
    TD := 0.2,
    Deviation_Limit := 2.0,
    Inhibit := LoopInhibit_OR);

(* Outputs published to other sections / HMI. *)
MM701_Moisture_PV := MM_701.PV;
PT701_HydraulicPressure_PV := PT_701.PV;
TT102_ShowerWaterTemp_PV := TT_102.PV;
PV101_Pressure_Command_Pct := LIC_701.XOUT;
PV101_Position_Feedback_Pct := PV_101.Feedback_Pos;
ESD_Trip := PT_701.High_Alarm;

FT_901(
    PV_Low := 5.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
FT_902(
    Scaling_Slope := 31.25,
    Scaling_Offset := -125.0,
    Alarm_Enable := TRUE);
CW_901(
    Alarm_Enable := TRUE);
FT901_LowOrFault_OR := FT_901.Low_Alarm OR FT_901.General_Fault;
XV_105();
XV105Closed_NOT := NOT XV_105.FB_Opened;
Interlock_PermissivesFail1_OR := XV105Closed_NOT OR FT901_LowOrFault_OR;
CW901DevTrip_OR := CW_901.High_Alarm OR CW_901.Low_Alarm;
CW901_DevOrFault_OR := CW901DevTrip_OR OR CW_901.General_Fault;
Interlock_PermissivesFail2_OR := FT_902.General_Fault OR CW901_DevOrFault_OR;
FFIC903_Inhibit_OR := Interlock_PermissivesFail1_OR OR Interlock_PermissivesFail2_OR;
FFIC_903(
    Auto := TRUE,
    PrimaryPV := FT_901.PV,
    SecondaryPV := FT_902.PV,
    RatioSP := 2.0,
    Bias := 0.0,
    MV_MIN := 0.0,
    MV_MAX := 500.0,
    Inhibit := FFIC903_Inhibit_OR);
NipLoadOK_NOT := NOT FT_901.Low_Alarm;
SP_LowCut_SEL := SEL(G := NipLoadOK_NOT, IN0 := 0.0, IN1 := FFIC_903.SlaveSP);
FIC_904(
    AUTO := TRUE,
    PV := FT_902.PV,
    SP := SP_LowCut_SEL,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    Deviation_Limit := 5.0);
FV_104(
    Control_Signal := FIC_904.XOUT,
    Manual_Mode := FALSE,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FFIC903_Inhibit_OR);

(* Outputs published to other sections / HMI. *)
FT901_NipLoad_kN := FT_901.PV;
FT902_FlowRate_Lmin := FT_902.PV;
FIC904_Flow_SP_FromRatio := FFIC_903.SlaveSP;
